ALTER TABLE `configuracion_bbdd` ADD COLUMN `tls_habilitado` TINYINT NOT NULL DEFAULT 1 COMMENT 'Decisión explícita de transporte por configuración: 1 exige TLS con certificado e identidad verificados; 0 permite conexión sin TLS con advertencia visible de que contraseña y datos pueden viajar sin cifrar. Por defecto todas las configuraciones existentes y nuevas requieren TLS. No altera AES-GCM de la contraseña almacenada ni autoriza reintentos automáticos sin cifrado.', ADD CONSTRAINT `CK_cbbdd_tls` CHECK (`tls_habilitado` IN (0,1));
